SELECT

FROM PERF_TARGET_VALUE
WHERE plan_id = #{planId}
  AND subject_type = #{subjectType}
  AND subject_id = #{subjectId}
  AND cycle_key = #{cycleKey}
  AND metric_code = #{metricCode}
LIMIT 1

SELECT

FROM PERF_TARGET_VALUE

    AND plan_id = #{planId}

        AND subject_type = #{subjectType}


        AND subject_id = #{subjectId}


        AND cycle_key = #{cycleKey}


ORDER BY subject_type ASC, subject_id ASC, cycle_key ASC, metric_code ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM PERF_TARGET_VALUE

    AND plan_id = #{planId}

        AND subject_type = #{subjectType}


        AND subject_id = #{subjectId}


        AND cycle_key = #{cycleKey}

