ORDER BY subject_type ASC, subject_id ASC, cycle_key ASC, metric_code ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM PERF_TARGET_VALUE


        AND plan_id = #{planId}


